function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string | number; sessionId: string}}
): Promise<void> {
  if (!sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Session history is not supported');
    return;
  }

  try {
    const sessions = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    const response: OutgoingMessage = {
      type: 'session_list',
      sessions: sessions.map(s => ({
        sessionId: s.sessionId,
        createdAt: typeof s.createdAt === 'string' ? s.createdAt : s.createdAt.toISOString(),
        updatedAt: typeof s.updatedAt === 'string' ? s.updatedAt : s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      })),
    };
    sendJson(ws, response);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listFor failed', {sessionId: session.sessionId, userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve session history');
  }
}

